[HttpPost("/pedidos/{id}/cerrar")]
public IActionResult Cerrar(int id, [FromServices] TiendaDbContext db)
{
    _ = Task.Run(async () =>
    {
        db.Auditoria.Add(new Auditoria { PedidoId = id, Accion = "cerrar" });
        await db.SaveChangesAsync();
    });

    return Accepted();
}
